function wc_schema():array{return [
 "CREATE TABLE IF NOT EXISTS wc_sites(tenant_id BIGINT UNSIGNED PRIMARY KEY,public_token CHAR(40) NOT NULL UNIQUE,theme VARCHAR(20) NOT NULL DEFAULT 'calm',seo_title VARCHAR(180) NOT NULL,seo_description VARCHAR(300) NOT NULL,active TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS wc_domains(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,hostname VARCHAR(253) NOT NULL UNIQUE,verify_token CHAR(48) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS wc_content(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,slug VARCHAR(100) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',author_id BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NULL,review_note VARCHAR(500) NULL,staff_id BIGINT UNSIGNED NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,capacity INT NOT NULL DEFAULT 0,fee_kobo BIGINT NOT NULL DEFAULT 0,consent_note VARCHAR(500) NULL,filename VARCHAR(180) NULL,mime VARCHAR(100) NULL,filedata MEDIUMBLOB NULL,published_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,status,kind,slug)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS wc_enquiries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,crm_enquiry_id BIGINT UNSIGNED NOT NULL,nonce CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_form(tenant_id,nonce),INDEX(tenant_id,ip_hash,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS wc_tours(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,content_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40) NOT NULL,status VARCHAR(24) NOT NULL,public_token CHAR(64) NOT NULL UNIQUE,nonce CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,amount_kobo BIGINT NOT NULL,expires_at DATETIME NOT NULL,reference VARCHAR(100) NULL UNIQUE,checkout_url VARCHAR(1500) NULL,verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_booking(tenant_id,nonce),INDEX(tenant_id,content_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function wc_host(string $raw):string{$host=strtolower(trim($raw));if(strlen($host)>253||!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/D',$host)||filter_var($host,FILTER_VALIDATE_IP))throw new RuntimeException('Use a DNS hostname such as www.yourschool.edu.ng.');return $host;}
