function wc_form_guard(array $site):string{
 $csrf=is_string($_POST['csrf']??null)?$_POST['csrf']:'';$nonce=op_text('nonce',64,true);if(!hash_equals((string)($_SESSION['csrf']??''),$csrf)||!preg_match('/^[a-f0-9]{64}$/D',$nonce)||!hash_equals((string)($_SESSION['wc_nonce']??''),$nonce)||op_text('website',100)!=='')throw new RuntimeException('Form expired or unavailable. Reload and try again.');if(op_text('privacy_consent',10)!=='yes')throw new RuntimeException('Consent to the school processing this enquiry / booking is required.');$ip=hash('sha256',(string)($_SERVER['REMOTE_ADDR']??''));$count=(int)g('SELECT COUNT(*) FROM wc_enquiries WHERE tenant_id=? AND ip_hash=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)',[$site['tenant_id'],$ip])+(int)g('SELECT COUNT(*) FROM wc_tours WHERE tenant_id=? AND ip_hash=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)',[$site['tenant_id'],$ip]);if($count>=10)throw new RuntimeException('Too many requests. Contact the school directly.');return $ip;
