function wc_public(array $site,?array $preview=null):void{
 $tid=(int)$site['tenant_id'];$token=$site['public_token'];$query='?school='.$token;$notice='';$booking=null;
 header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: SAMEORIGIN');header('Cache-Control: private, no-store');
