 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&!$preview){try{
  if(isset($_POST['wc_public_action'])){$notice=wc_submit($site,op_text('wc_public_action',20,true));$_SESSION['wc_flash_'.$tid]=$notice;$b=$_SESSION['wc_booking']??null;unset($_SESSION['wc_booking']);header('Location: index.php'.$query.($b?'&booking='.$b:''),true,303);exit;}
  if(isset($_POST['wc_payment'])){if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('Form expired.');$result=wc_payment($tid,is_string($_GET['booking']??null)?$_GET['booking']:'',sv_enum('wc_payment',['initialize','verify']));$notice=$result['status']==='paid_review'?'Payment verified; contact school staff to resolve the booking.':'Payment record updated. A bank debit or checkout redirect alone does not confirm payment.';}
 }catch(Throwable $e){$notice=$e->getMessage();}}
