function wc_public_form(string $action,int $content):void{echo '<form method="post"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="nonce" value="'.e($_SESSION['wc_nonce']).'"><input type="hidden" name="wc_public_action" value="'.$action.'"><input type="hidden" name="content_id" value="'.$content.'"><div style="display:none"><input name="website" tabindex="-1" autocomplete="off"></div>';foreach(['name'=>'Your name','email'=>'Email','phone'=>'Phone'] as $key=>$label)echo '<label>'.$label.'<input name="'.$key.'" type="'.($key==='email'?'email':'text').'" required maxlength="190"></label>';if($action==='enquiry')echo '<label>Class / area of interest<input name="interest" required maxlength="150"></label><label>Your enquiry<textarea name="message" required maxlength="1500"></textarea></label>';echo '<label class="check"><input type="checkbox" name="privacy_consent" value="yes" required>I consent to the school using these details to respond to this enquiry / manage this booking. This does not subscribe me to marketing.</label><button>'.($action==='tour'?'Request one tour place':'Send enquiry').'</button></form>';}
