  if($view==='approval'&&$approver){sv_form('wc_review',['content_id'=>['Submitted content ID','number'],'status'=>['Decision',['published'=>'Publish / replace prior revision','rejected'=>'Reject']],'review_note'=>['Review / consent / factual checks','textarea']],'Review as a different approver');sv_form('wc_archive',['content_id'=>['Published content ID','number']],'Withdraw published content');}echo '<p>Published content is immutable. Create another draft with the same type and slug to replace it; the old revision remains public until independent approval. Live booked tours require a new slug. Public staff profiles use only submitted content; HR records are never published automatically.</p>';
